from models import SearchRange
from predicates import is_monotonic

class RangeSearcher:
    def find_range(self, nums: list[int], target: int) -> SearchRange:
        if not nums:
            return SearchRange(-1, -1, 0)

        low, high = 0, len(nums) - 1
        first = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                first = mid
                high = mid - 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1

        low, high = 0, len(nums) - 1
        last = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                last = mid
                low = mid + 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1

        count = (last - first + 1) if (first != -1 and last != -1) else 0
        return SearchRange(first, last, count)
